package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.jxpath.Expression;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CoreOperationCompare_findMatch_TriageGen0Test {

    private CoreOperationCompare sut;
    private Expression mockExpr1;
    private Expression mockExpr2;

    @Before
    public void setUp() {
        mockExpr1 = mock(Expression.class);
        mockExpr2 = mock(Expression.class);
        // Since findMatch is protected, we use a spy or a subclass to access it
        sut = spy(new CoreOperationCompare(mockExpr1, mockExpr2));
    }

    /**
     * Helper class to access protected method for testing
     */
    private static class TestableCoreOperationCompare extends CoreOperationCompare {
        public TestableCoreOperationCompare(Expression arg1, Expression arg2) {
            super(arg1, arg2);
        }

        @Override
        public boolean findMatch(Iterator lit, Iterator rit) {
            return super.findMatch(lit, rit);
        }
    }

    @Test
    public void testFindMatch_BothIteratorsEmpty() {
        TestableCoreOperationCompare testableSut = new TestableCoreOperationCompare(mockExpr1, mockExpr2);
        Iterator<Object> lit = Collections.emptyIterator();
        Iterator<Object> rit = Collections.emptyIterator();

        boolean result = testableSut.findMatch(lit, rit);

        assertFalse("Should return false when both are empty", result);
    }

    @Test
    public void testFindMatch_LitEmptyRitNotEmpty() {
        TestableCoreOperationCompare testableSut = new TestableCoreOperationCompare(mockExpr1, mockExpr2);
        Iterator<Object> lit = Collections.emptyIterator();
        Iterator<Object> rit = Arrays.asList("A", "B").iterator();

        // contains() will be called, but left HashSet is empty
        // We stub contains to return false for any input when left is empty
        doReturn(false).when(testableSut).contains(any(), any());

        boolean result = testableSut.findMatch(lit, rit);

        assertFalse("Should return false when left iterator is empty", result);
    }

    @Test
    public void testFindMatch_LitNotEmptyRitEmpty() {
        TestableCoreOperationCompare testableSut = new TestableCoreOperationCompare(mockExpr1, mockExpr2);
        Iterator<Object> lit = Arrays.asList("A", "B").iterator();
        Iterator<Object> rit = Collections.emptyIterator();

        boolean result = testableSut.findMatch(lit, rit);

        assertFalse("Should return false when right iterator is empty", result);
    }

    @Test
    public void testFindMatch_MatchFound() {
        TestableCoreOperationCompare testableSut = new TestableCoreOperationCompare(mockExpr1, mockExpr2);
        Iterator<Object> lit = Arrays.asList("A", "B").iterator();
        Iterator<Object> rit = Arrays.asList("C", "B").iterator();

        // Mock contains to return true when it encounters "B"
        // The first call in the loop for "C" returns false, second for "B" returns true
        doReturn(false).doReturn(true).when(testableSut).contains(any(), any());

        boolean result = testableSut.findMatch(lit, rit);

        assertTrue("Should return true when a match is found", result);
        verify(testableSut, atLeastOnce()).contains(any(), eq("B"));
    }

    @Test
    public void testFindMatch_NoMatchFound() {
        TestableCoreOperationCompare testableSut = new TestableCoreOperationCompare(mockExpr1, mockExpr2);
        Iterator<Object> lit = Arrays.asList("A", "B").iterator();
        Iterator<Object> rit = Arrays.asList("C", "D").iterator();

        // Mock contains to always return false
        doReturn(false).when(testableSut).contains(any(), any());

        boolean result = testableSut.findMatch(lit, rit);

        assertFalse("Should return false when no elements match", result);
    }

    @Test
    public void testFindMatch_SingleElementMatch() {
        TestableCoreOperationCompare testableSut = new TestableCoreOperationCompare(mockExpr1, mockExpr2);
        Iterator<Object> lit = Collections.singletonList("X").iterator();
        Iterator<Object> rit = Collections.singletonList("X").iterator();

        doReturn(true).when(testableSut).contains(any(), eq("X"));

        boolean result = testableSut.findMatch(lit, rit);

        assertTrue("Should return true for single element match", result);
    }
}
